Given an integer array arr[] and an integer x, determine whether there exist four distinct elements in the array whose sum is equal to x. Return true if such four elements exist. Otherwise, return false.Examples:Input: arr[] = [1, 5, 1, 0, 6, 0], x = 7Output: trueExplanation: The four elements 1, 5, 1, 0 have a sum equal to 7.Input: arr[] = [1, 2, 3, 4, 5], x = 50Output: falseExplanation: No combination of four distinct elements has a sum equal to 50.Try It YourselfTable of Content[Naive Approach] Checking Every Quadruplet - O(n ^ 4) Time and O(1) Space[Better Approach] Sorting and Two Pointers - O(n ^ 3) Time and O(1) Space[Expected Approach] Using Pair Sums - O(n ^ 2) Time and O(n ^ 2) Space[Naive Approach] Checking Every Quadruplet - O(n ^ 4) Time and O(1) SpaceThe idea is to generate every possible combination of four distinct indices and check whether the sum of their elements is equal to x. If any quadruplet has the required sum, return true. Otherwise, return false.
            C++

    #include <iostream>
#include <vector>
using namespace std;

bool fourSum(vector<int>& arr, int x) {
    int n = arr.size();

    // Check every possible quadruplet.
    for (int i = 0; i < n - 3; i++) {
        for (int j = i + 1; j < n - 2; j++) {
            for (int k = j + 1; k < n - 1; k++) {
                for (int l = k + 1; l < n; l++) {
                    if (arr[i] + arr[j] + arr[k] + arr[l] == x) {
                        return true;
                    }
                }
            }
        }
    }

    return false;
}

int main() {
    vector<int> arr1 = {1, 5, 1, 0, 6, 0};
    int x1 = 7;
    cout << boolalpha << fourSum(arr1, x1) << endl;

    vector<int> arr2 = {1, 2, 3, 4, 5};
    int x2 = 50;
    cout << boolalpha << fourSum(arr2, x2) << endl;

    return 0;
}


